from fastapi import FastAPI, Request

app = FastAPI()

@app.middleware("http")
async def add_header(request: Request, call_next):
    response = await call_next(request)
    response.headers["X-Processed-By"] = "FastAPI"
    return response

@app.get("/")
async def root():
    return {"message": "Hello"}
